add_action( 'init', 'perfectpixel_stacked_tabs_setup' );

function perfectpixel_stacked_tabs_setup() {
	remove_action( 'woocommerce_after_single_product_summary', 'woocommerce_output_product_data_tabs', 10 );
	add_action( 'woocommerce_after_single_product_summary', 'perfectpixel_stacked_tabs_output', 10 );
}

function perfectpixel_stacked_tabs_output() {
	$tabs = apply_filters( 'woocommerce_product_tabs', array() );
	if ( ! $tabs ) {
		return;
	}
	echo '<div class="woocommerce-tabs perfectpixel-stacked-tabs" style="clear:both">';
	foreach ( $tabs as $key => $tab ) {
		if ( empty( $tab['callback'] ) || ! is_callable( $tab['callback'] ) ) {
			continue;
		}
		echo '<section id="tab-' . esc_attr( $key ) . '" class="perfectpixel-stacked-tab" style="margin-bottom:2em">';
		call_user_func( $tab['callback'], $key, $tab );
		echo '</section>';
	}
	echo '</div>';
}
